						av->DamageActorValue(RE::ActorValue::kHealth, std::min(100.f, std::max(0.f, av->GetActorValue(RE::ActorValue::kHealth) - 1.f)));
						g_ctx["damaged_hp"] = av->GetActorValue(RE::ActorValue::kHealth);
