						duration = a.value("remaining",0.0) > 10 && a.value("remaining",0.0) <= 12;
					native = Cast::TalentDiagnostics().value("grasp_procs",0) > 0 && duration && enemy->AsActorValueOwner()->GetActorValue(RE::ActorValue::kSpeedMult) < 1;
