                    checks[stage==4 ? "charge_too_close" : stage==5 ? "charge_in_range" : "charge_too_far"]=
                        (stage==4 ? distance<lo : stage==5 ? distance>=lo && distance<=hi : distance>hi) && eval("IsActionInRange(1)")==(stage==5 ? "1" : "0");
                    if (stage==4) place((lo+hi)/2);
